-- 12 padres mapeados, incluido JD9558; cuatro adicionales separados.
SELECT m.sku, EXISTS (SELECT 1 FROM catalog.variant_images i JOIN catalog.variants v ON v.id=i.variant_id
    JOIN catalog.products p ON p.id=v.product_id WHERE i.id=m.source_image_id::uuid
    AND v.id=m.source_variant_id::uuid AND p.id=m.product_id::uuid AND p.sku_base=m.sku
    AND p.tiene_variantes AND i.url=m.url) AND EXISTS (SELECT 1 FROM storage.objects o JOIN storage.buckets b ON b.id=o.bucket_id
    WHERE b.id='catalog-products' AND b.public AND o.name=m.file AND o.id=m.storage_id::uuid
      AND o.metadata->>'eTag'=m.etag AND (o.metadata->>'size')::bigint>0 AND o.metadata->>'mimetype' LIKE 'image/%') AND EXISTS (SELECT 1 FROM catalog.product_images i JOIN storage.objects o
  ON i.url='https://slzglmtiyrzygpkiuthf.supabase.co/storage/v1/object/public/catalog-products/'||o.name AND o.bucket_id='catalog-products'
  WHERE i.product_id=m.product_id::uuid AND i.url=m.url AND (o.metadata->>'size')::bigint>0
